from pathlib import Path
r='.lines[data-el="roundrise-chart-line"]'
s='''R{container-type:size;position:relative;anchor-scope:all;display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);padding:0;min-width:0;min-height:0;--roundrise-plot:calc(100cqh - var(--gap-lg)*2);font-family:var(--font-body);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink);background:repeating-linear-gradient(to top,var(--n-2) 0 1px,var(--page) 1px 25%)}R>.pt{position:static;align-self:start;justify-self:center;width:0;height:0;margin-top:calc(var(--gap-lg) + (1 - var(--v)/var(--max,100))*var(--roundrise-plot));anchor-name:var(--roundrise-self);--roundrise-vh:calc(var(--roundrise-plot)*var(--v)/var(--max,100))}R>.pt>b{display:block;position:relative;z-index:2;white-space:nowrap;width:max-content;transform:translate(-50%,calc(-100% - var(--gap-sm)));font-size:var(--type-20);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);color:var(--a1-7)}R>.pt>b:after{content:'';position:absolute;left:calc(50% - 5px);top:calc(100% + var(--gap-sm) - 5px);width:10px;height:10px;border-radius:50%;background:var(--a1)}R>.pt>span{position:absolute;left:anchor(var(--roundrise-self) center);bottom:0;transform:translateX(-50%);height:var(--gap-lg);display:flex;align-items:center;justify-content:center;white-space:nowrap;font-size:var(--type-16);font-weight:var(--label-weight);line-height:var(--label-line);color:var(--n-7)}R>.pt:before{content:'';position:absolute;left:anchor(var(--roundrise-prev) center);right:anchor(var(--roundrise-self) center);top:calc(anchor(var(--roundrise-prev) top) - var(--roundrise-plot));bottom:var(--gap-lg);clip-path:polygon(0 calc(var(--roundrise-plot) - 1px),100% calc(100% - var(--roundrise-vh) - 1px),100% calc(100% - var(--roundrise-vh) + 1px),0 calc(var(--roundrise-plot) + 1px));background:var(--a1);pointer-events:none}R>.pt:first-child:before{content:none}@container (max-width:600px){R>.pt>b{font-size:var(--type-16)}R>.pt>span{font-size:var(--type-14)}}@container (max-width:400px){R>.pt:nth-child(even)>span{visibility:hidden}R>.pt>b{font-size:var(--type-14)}}'''
for i in range(1,13):s+=f'R>.pt:nth-child({i}){{--roundrise-self:--roundrise-line-{i};--roundrise-prev:--roundrise-line-{i-1};}}'
Path('/workspace/output/roundrise/elements/chart-line/element.css').write_text(s.replace('R',r))
